content:
:root {
  --primary-color: #3b82f6;
  --primary-hover: #2563eb;
  --primary-light: #eff6ff;
  --text-main: #1e293b;
  --text-muted: #64748b;
  --text-light: #94a3b8;
  --bg-gradient-start: #f1f5f9;
  --bg-gradient-end: #e2e8f0;
  --card-bg: #ffffff;
  --border-color: #e2e8f0;
  --border-focus: #3b82f6;
  --danger-color: #ef4444;
  --danger-hover: #dc2626;
  --danger-light: #fef2f2;
  --success-color: #10b981;
  --shadow-sm: 0 1px 2px 0 rgba(0, 0, 0, 0.05);
  --shadow-md: 0 4px 6px -1px rgba(0, 0, 0, 0.1), 0 2px 4px -2px rgba(0, 0, 0, 0.1);
  --shadow-lg: 0 10px 15px -3px rgba(0, 0, 0, 0.1), 0 4px 6px -4px rgba(0, 0, 0, 0.1);
  --radius-sm: 6px;
  --radius-md: 10px;
  --radius-lg: 16px;
  --font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, "Hiragino Kaku Gothic ProN", "Hiragino Sans", Meiryo, sans-serif;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: var(--font-family);
  background: linear-gradient(135deg, var(--bg-gradient-start) 0%, var(--bg-gradient-end) 100%);
  color: var(--text-main);
  min-height: 100vh;
  display: flex;
  justify-content: center;
  align-items: flex-start;
  padding: 32px 16px;
  line-height: 1.5;
  -webkit-font-smoothing: antialiased;
}

#root {
  width: 100%;
  display: flex;
  justify-content: center;
}

/* メインコンテナ */
.todo-app {
  width: 100%;
  max-width: 540px;
  margin: 0 auto;
}

/* カード */
.app-card {
  background-color: var(--card-bg);
  border-radius: var(--radius-lg);
  box-shadow: var(--shadow-lg);
  padding: 32px 28px;
  border: 1px solid rgba(255, 255, 255, 0.7);
}

/* ヘッダー */
.app-header {
  margin-bottom: 24px;
  text-align: center;
}

.app-title {
  font-size: 1.75rem;
  font-weight: 700;
  color: var(--text-main);
  letter-spacing: -0.02em;
  margin-bottom: 6px;
}

.app-subtitle {
  font-size: 0.9rem;
  color: var(--text-muted);
}

/* タスク入力フォーム */
.todo-form {
  display: flex;
  gap: 10px;
  margin-bottom: 20px;
}

.todo-input {
  flex: 1;
  padding: 12px 16px;
  font-size: 0.95rem;
  color: var(--text-main);
  background-color: #f8fafc;
  border: 1.5px solid var(--border-color);
  border-radius: var(--radius-md);
  outline: none;
  transition: all 0.2s ease;
  font-family: inherit;
}

.todo-input::placeholder {
  color: var(--text-light);
}

.todo-input:focus {
  background-color: #ffffff;
  border-color: var(--border-focus);
  box-shadow: 0 0 0 3px rgba(59, 130, 246, 0.15);
}

.add-button {
  padding: 12px 20px;
  font-size: 0.95rem;
  font-weight: 600;
  color: #ffffff;
  background-color: var(--primary-color);
  border: none;
  border-radius: var(--radius-md);
  cursor: pointer;
  transition: background-color 0.2s ease, transform 0.1s ease;
  white-space: nowrap;
  font-family: inherit;
  display: flex;
  align-items: center;
  justify-content: center;
}

.add-button:hover {
  background-color: var(--primary-hover);
}

.add-button:active {
  transform: scale(0.98);
}

.add-button:disabled {
  background-color: #cbd5e1;
  cursor: not-allowed;
  transform: none;
}

/* フィルター */
.filter-container {
  display: flex;
  background-color: #f1f5f9;
  border-radius: var(--radius-md);
  padding: 4px;
  gap: 4px;
  margin-bottom: 20px;
}

.filter-btn {
  flex: 1;
  padding: 8px 12px;
  font-size: 0.875rem;
  font-weight: 500;
  color: var(--text-muted);
  background: transparent;
  border: none;
  border-radius: var(--radius-sm);
  cursor: pointer;
  transition: all 0.2s ease;
  font-family: inherit;
  text-align: center;
}

.filter-btn:hover {
  color: var(--text-main);
}

.filter-btn-active {
  background-color: #ffffff;
  color: var(--primary-color);
  font-weight: 600;
  box-shadow: var(--shadow-sm);
}

/* ステータスバー */
.stats-bar {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 8px 4px 16px;
  border-bottom: 1px solid var(--border-color);
  margin-bottom: 12px;
  font-size: 0.85rem;
  color: var(--text-muted);
}

.badge {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  background-color: var(--primary-light);
  color: var(--primary-color);
  font-weight: 600;
  padding: 2px 8px;
  border-radius: 9999px;
  margin-left: 6px;
}

.clear-completed-btn {
  background: none;
  border: none;
  color: var(--text-muted);
  font-size: 0.825rem;
  cursor: pointer;
  padding: 4px 8px;
  border-radius: var(--radius-sm);
  transition: all 0.2s ease;
  font-family: inherit;
}

.clear-completed-btn:hover {
  color: var(--danger-color);
  background-color: var(--danger-light);
}

/* タスク一覧 */
.todo-list {
  list-style: none;
  display: flex;
  flex-direction: column;
  gap: 10px;
  max-height: 480px;
  overflow-y: auto;
  padding-right: 2px;
}

/* スクロールバーのカスタマイズ */
.todo-list::-webkit-scrollbar {
  width: 6px;
}

.todo-list::-webkit-scrollbar-track {
  background: transparent;
}

.todo-list::-webkit-scrollbar-thumb {
  background: #cbd5e1;
  border-radius: 3px;
}

.todo-list::-webkit-scrollbar-thumb:hover {
  background: #94a3b8;
}

/* 空表示 */
.todo-empty {
  text-align: center;
  padding: 40px 20px;
  color: var(--text-light);
  font-size: 0.95rem;
}

/* タスクアイテム */
.todo-item {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 12px 14px;
  background-color: #ffffff;
  border: 1px solid var(--border-color);
  border-radius: var(--radius-md);
  transition: all 0.2s ease;
}

.todo-item:hover {
  border-color: #cbd5e1;
  box-shadow: var(--shadow-sm);
}

.todo-item-completed {
  background-color: #f8fafc;
  border-color: #e2e8f0;
}

/* チェックボックスコンテナ */
.checkbox-label {
  display: flex;
  align-items: flex-start;
  gap: 12px;
  flex: 1;
  cursor: pointer;
  user-select: none;
  min-width: 0;
}

.checkbox-input {
  position: absolute;
  opacity: 0;
  width: 0;
  height: 0;
}

.checkbox-custom {
  width: 20px;
  height: 20px;
  border: 2px solid #cbd5e1;
  border-radius: 6px;
  display: flex;
  align-items: center;
  justify-content: center;
  margin-top: 2px;
  flex-shrink: 0;
  transition: all 0.2s ease;
  background-color: #ffffff;
}

.checkbox-input:checked + .checkbox-custom {
  background-color: var(--success-color);
  border-color: var(--success-color);
}

.checkbox-custom::after {
  content: "";
  display: none;
  width: 5px;
  height: 10px;
  border: solid #ffffff;
  border-width: 0 2px 2px 0;
  transform: rotate(45deg);
  margin-bottom: 2px;
}

.checkbox-input:checked + .checkbox-custom::after {
  display: block;
}

.checkbox-input:focus-visible + .checkbox-custom {
  box-shadow: 0 0 0 3px rgba(59, 130, 246, 0.3);
}

/* タスク本文エリア */
.todo-text {
  font-size: 0.95rem;
  color: var(--text-main);
  word-break: break-word;
  transition: color 0.2s ease;
  line-height: 1.4;
}

.todo-item-completed .todo-text {
  text-decoration: line-through;
  color: var(--text-light);
}

.todo-date {
  font-size: 0.75rem;
  color: var(--text-light);
  margin-top: 3px;
  display: block;
}

/* 削除ボタン */
.delete-btn {
  background: transparent;
  border: none;
  color: var(--text-light);
  cursor: pointer;
  padding: 6px;
  border-radius: var(--radius-sm);
  display: flex;
  align-items: center;
  justify-content: center;
  transition: all 0.2s ease;
  margin-left: 8px;
  flex-shrink: 0;
}

.delete-btn:hover {
  color: var(--danger-color);
  background-color: var(--danger-light);
}

.delete-btn:active {
  transform: scale(0.92);
}

/* レスポンシブ対応 */
@media (max-width: 480px) {
  body {
    padding: 16px 10px;
  }

  .app-card {
    padding: 24px 16px;
  }

  .app-title {
    font-size: 1.5rem;
  }

  .todo-form {
    flex-direction: column;
    gap: 8px;
  }

  .add-button {
    width: 100%;
    padding: 10px;
  }

  .stats-bar {
    flex-direction: column;
    align-items: flex-start;
    gap: 8px;
  }

  .clear-completed-btn {
    padding-left: 0;
  }
}

export interface TodoItemData {
  id: string;
  text: string;
  completed: boolean;
  createdAt: string;
}

export type FilterType = 'all' | 'active' | 'completed';

export interface TodoInputProps {
  onAddTodo: (text: string) => void;
}

export interface TodoItemProps {
  todo: TodoItemData;
  onToggle: (id: string) => void;
  onDelete: (id: string) => void;
}

import { useState, FormEvent, ChangeEvent } from 'react';
import { Plus } from 'lucide-react';
import { TodoInputProps } from '../types';

const TodoInput = ({ onAddTodo }: TodoInputProps) => {
  const [inputText, setInputText] = useState('');

  const handleSubmit = (e: FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    const trimmed = inputText.trim();
    if (!trimmed) {
      return;
    }
    onAddTodo?.(trimmed);
    setInputText('');
  };

  const handleChange = (e: ChangeEvent<HTMLInputElement>) => {
    setInputText(e.target.value);
  };

  const isButtonDisabled = inputText.trim().length === 0;

  return (
    <form className="todo-form" onSubmit={handleSubmit}>
      <input
        type="text"
        className="todo-input"
        placeholder="新しいタスクを入力してください..."
        value={inputText}
        onChange={handleChange}
        autoFocus
      />
      <button
        type="submit"
        className="add-button"
        disabled={isButtonDisabled}
        aria-label="タスクを追加"
      >
        <Plus size={18} style={{ marginRight: 4 }} />
        追加
      </button>
    </form>
  );
};

export default TodoInput;

import { ChangeEvent } from 'react';
import { Trash2 } from 'lucide-react';
import { TodoItemProps } from '../types';

const TodoItem = ({ todo, onToggle, onDelete }: TodoItemProps) => {
  const handleCheckboxChange = (_e: ChangeEvent<HTMLInputElement>) => {
    onToggle?.(todo.id);
  };

  const handleDeleteClick = () => {
    onDelete?.(todo.id);
  };

  const itemClassName = todo.completed ? 'todo-item todo-item-completed' : 'todo-item';

  return (
    <li className={itemClassName}>
      <label className="checkbox-label">
        <input
          type="checkbox"
          className="checkbox-input"
          checked={todo.completed}
          onChange={handleCheckboxChange}
        />
        <span className="checkbox-custom" aria-hidden="true" />
        <div>
          <span className="todo-text">{todo.text}</span>
          <span className="todo-date">{todo.createdAt}</span>
        </div>
      </label>
      <button
        type="button"
        className="delete-btn"
        onClick={handleDeleteClick}
        aria-label={`${todo.text} を削除`}
        title="タスクを削除"
      >
        <Trash2 size={18} />
      </button>
    </li>
  );
};

export default TodoItem;

import { useState } from 'react';
import { TodoItemData, FilterType } from './types';
import TodoInput from './components/TodoInput';
import TodoItem from './components/TodoItem';

const INITIAL_TODOS: TodoItemData[] = [
  {
    id: '1',
    text: '牛乳と卵をスーパーで買う',
    completed: false,
    createdAt: '今日 09:30',
  },
  {
    id: '2',
    text: '企画書のドラフトをまとめてチームに共有する',
    completed: true,
    createdAt: '昨日 15:00',
  },
  {
    id: '3',
    text: '週末の歯医者の予約確認の電話を入れる',
    completed: false,
    createdAt: '今日 10:15',
  },
  {
    id: '4',
    text: '部屋の観葉植物に水やりをする',
    completed: false,
    createdAt: '今日 11:00',
  },
];

const formatCurrentTime = (): string => {
  const now = new Date();
  const hours = String(now.getHours()).padStart(2, '0');
  const minutes = String(now.getMinutes()).padStart(2, '0');
  return `今日 ${hours}:${minutes}`;
};

const App = () => {
  const [todos, setTodos] = useState<TodoItemData[]>(INITIAL_TODOS);
  const [filter, setFilter] = useState<FilterType>('all');

  const handleAddTodo = (text: string) => {
    const newTodo: TodoItemData = {
      id: Date.now().toString(),
      text,
      completed: false,
      createdAt: formatCurrentTime(),
    };
    setTodos((prev) => [newTodo, ...prev]);
  };

  const handleToggleTodo = (id: string) => {
    setTodos((prev) =>
      prev.map((todo) =>
        todo.id === id ? { ...todo, completed: !todo.completed } : todo
      )
    );
  };

  const handleDeleteTodo = (id: string) => {
    setTodos((prev) => prev.filter((todo) => todo.id !== id));
  };

  const handleClearCompleted = () => {
    setTodos((prev) => prev.filter((todo) => !todo.completed));
  };

  const activeCount = todos.filter((todo) => !todo.completed).length;
  const completedCount = todos.length - activeCount;

  const filteredTodos = todos.filter((todo) => {
    if (filter === 'active') {
      return !todo.completed;
    }
    if (filter === 'completed') {
      return todo.completed;
    }
    return true;
  });

  return (
    <main className="todo-app">
      <div className="app-card">
        <header className="app-header">
          <h1 className="app-title">やることリスト</h1>
          <p className="app-subtitle">今日のタスクを整理して、すっきり一日を過ごしましょう</p>
        </header>

        <TodoInput onAddTodo={handleAddTodo} />

        <div className="filter-container" role="tablist" aria-label="タスクの絞り込み">
          <button
            type="button"
            className={filter === 'all' ? 'filter-btn filter-btn-active' : 'filter-btn'}
            onClick={() => setFilter('all')}
          >
            すべて
          </button>
          <button
            type="button"
            className={filter === 'active' ? 'filter-btn filter-btn-active' : 'filter-btn'}
            onClick={() => setFilter('active')}
          >
            未完了
          </button>
          <button
            type="button"
            className={filter === 'completed' ? 'filter-btn filter-btn-active' : 'filter-btn'}
            onClick={() => setFilter('completed')}
          >
            完了済み
          </button>
        </div>

        <div className="stats-bar">
          <div>
            <span>残りタスク</span>
            <span className="badge">{activeCount}</span>
          </div>
          {completedCount > 0 && (
            <button
              type="button"
              className="clear-completed-btn"
              onClick={handleClearCompleted}
            >
              完了済みを削除 ({completedCount})
            </button>
          )}
        </div>

        {filteredTodos.length === 0 ? (
          <div className="todo-empty">
            {filter === 'active' && '未完了のタスクはありません 🎉'}
            {filter === 'completed' && '完了済みのタスクはありません'}
            {filter === 'all' && 'タスクがありません。上の入力欄から追加してください'}
          </div>
        ) : (
          <ul className="todo-list">
            {filteredTodos.map((todo) => (
              <TodoItem
                key={todo.id}
                todo={todo}
                onToggle={handleToggleTodo}
                onDelete={handleDeleteTodo}
              />
            ))}
          </ul>
        )}
      </div>
    </main>
  );
};

export default App;
